public class TargetPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String colorAt(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "(null image)";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static String hex(java.awt.Color c) {
        return String.format("#%06X", c.getRGB() & 0xFFFFFF);
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage img =
                    new java.awt.image.BufferedImage(90, 90, java.awt.image.BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D g = img.createGraphics();
            try {
                TargetPainter.paint(g, 90);
            } finally {
                g.dispose();
            }
            check("size 90: bull's eye is red", hex(java.awt.Color.RED), colorAt(img, 45, 45));
            check("size 90: middle ring is white", hex(java.awt.Color.WHITE), colorAt(img, 67, 45));
            check("size 90: outer ring is red", hex(java.awt.Color.RED), colorAt(img, 82, 45));
            check("size 90: corner background is white", hex(java.awt.Color.WHITE), colorAt(img, 3, 3));
            java.awt.image.BufferedImage img2 =
                    new java.awt.image.BufferedImage(60, 60, java.awt.image.BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D g2 = img2.createGraphics();
            try {
                TargetPainter.paint(g2, 60);
            } finally {
                g2.dispose();
            }
            check("size 60: bull's eye is red", hex(java.awt.Color.RED), colorAt(img2, 30, 30));
            check("size 60: middle ring is white", hex(java.awt.Color.WHITE), colorAt(img2, 45, 30));
            check("size 60: outer ring is red", hex(java.awt.Color.RED), colorAt(img2, 55, 30));
            check("size 60: corner background is white", hex(java.awt.Color.WHITE), colorAt(img2, 2, 2));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
